using System.Buffers.Binary;
using System.IO.Compression;
using System.Text.Json;
using ArtGen;
using Core.Tests.Content;
using Json.Schema;

namespace Core.Tests.Art;

/// <summary>Placeholder art generated by tools/ArtGen (ADR 0010).</summary>
public sealed class AtlasTests
{
    private static readonly string[] _biomes = ["meadow", "forest", "mountain", "wasteland"];
    private static readonly string[] _objectIds =
        ["tree", "rock", "ore", "berry_bush", "poi_chest", "poi_ruins", "poi_lair", "settlement_site", "start_marker", "coal", "ore_vein", "coal_vein", "hero",
         "resident_carrier", "resident_lumberjack", "resident_stonemason", "resident_farmer", "resident_miner", "resident_guard", "resident_specialist", "resident_unemployed",
         "sapling", "stump"];

    // Every building of data/buildings has at least level 1 (BuildingSpecsMatchTheBuildingData checks the full list).
    private static readonly string[] _buildingIds = ["campfire", "house", "storage", "field", "sawmill", "stonecutter"];

    [Fact]
    public void GenerationIsDeterministic()
    {
        ArtOutput a = ArtGenerator.Generate();
        ArtOutput b = ArtGenerator.Generate();

        Assert.True(a.TilesPng.AsSpan().SequenceEqual(b.TilesPng));
        Assert.True(a.ObjectsPng.AsSpan().SequenceEqual(b.ObjectsPng));
        Assert.True(a.BuildingsPng.AsSpan().SequenceEqual(b.BuildingsPng));
        Assert.Equal(a.AtlasJson, b.AtlasJson);
        Assert.Equal(a.SchemaJson, b.SchemaJson);
    }

    [Fact]
    public void EveryRequiredIdIsPresentWithTheRightHeight()
    {
        ArtOutput art = ArtGenerator.Generate();
        HashSet<string> ids = art.Cells.Select(c => c.Id).ToHashSet(StringComparer.Ordinal);
        Assert.Equal(art.Cells.Count, ids.Count);

        foreach (string biome in _biomes)
        {
            for (int h = 0; h <= 3; h++)
            {
                for (int v = 0; v < TileArt.Variants; v++)
                {
                    Assert.Contains($"{biome}_h{h}_v{v}", ids);
                }
            }
        }

        for (int v = 0; v < TileArt.Variants; v++)
        {
            Assert.Contains($"water_h0_v{v}", ids);
            Assert.DoesNotContain($"water_h1_v{v}", ids);
            for (int h = 0; h <= 3; h++)
            {
                Assert.Contains($"river_h{h}_v{v}", ids);
            }
        }

        foreach (string id in _objectIds)
        {
            Assert.Contains(id, ids);
        }

        foreach (string building in _buildingIds)
        {
            for (int stage = 0; stage < BuildingArt.Stages; stage++)
            {
                Assert.Contains(BuildingArt.FrameId(building, 1, stage), ids);
            }
        }

        foreach (string kind in new[] { "trail", "road" })
        {
            for (int v = 0; v < 4; v++)
            {
                AtlasCell overlay = art.Cells.Single(c => c.Id == $"{kind}_v{v}");
                Assert.Equal(("tiles", "overlay", 32, 16, 16, 8, 0), (overlay.Atlas, overlay.Kind, overlay.W, overlay.H, overlay.OriginX, overlay.OriginY, overlay.Height));
                Assert.Equal(0, art.Tiles.Get(overlay.X, overlay.Y).A);
                Assert.NotEqual(0, art.Tiles.Get(overlay.X + 16, overlay.Y + 8).A);
            }
        }

        foreach (AtlasCell tile in art.Cells.Where(c => c.Kind == "tile"))
        {
            Assert.Equal(TileArt.TileWidth, tile.W);
            Assert.Equal(TileArt.TileHeight + (TileArt.HeightStep * tile.Height), tile.H);
            Assert.Equal(TileArt.TileWidth / 2, tile.OriginX);
            Assert.Equal((TileArt.TileHeight / 2) + (TileArt.HeightStep * tile.Height), tile.OriginY);
        }

        foreach (AtlasCell obj in art.Cells.Where(c => c.Kind == "object"))
        {
            Assert.Equal((32, 32, 16, 24), (obj.W, obj.H, obj.OriginX, obj.OriginY));
        }
    }

    [Fact]
    public void CellsAreInsideTheAtlasAndDoNotOverlap()
    {
        ArtOutput art = ArtGenerator.Generate();
        Dictionary<string, Canvas> atlases = new() { ["tiles"] = art.Tiles, ["objects"] = art.Objects, ["buildings"] = art.Buildings };

        foreach (IGrouping<string, AtlasCell> group in art.Cells.GroupBy(c => c.Atlas))
        {
            Canvas atlas = atlases[group.Key];
            AtlasCell[] cells = group.ToArray();
            foreach (AtlasCell c in cells)
            {
                Assert.True(c.X >= 0 && c.Y >= 0 && c.X + c.W <= atlas.Width && c.Y + c.H <= atlas.Height, c.Id + " leaves the atlas");
                Assert.True(c.OriginX < c.W && c.OriginY < c.H, c.Id + " origin outside the cell");
            }

            for (int i = 0; i < cells.Length; i++)
            {
                for (int j = i + 1; j < cells.Length; j++)
                {
                    AtlasCell a = cells[i];
                    AtlasCell b = cells[j];
                    bool overlap = a.X < b.X + b.W && b.X < a.X + a.W && a.Y < b.Y + b.H && b.Y < a.Y + a.H;
                    Assert.False(overlap, a.Id + " overlaps " + b.Id);
                }
            }
        }
    }

    [Fact]
    public void BuildingSpecsMatchTheBuildingData()
    {
        using JsonDocument doc = JsonDocument.Parse(File.ReadAllText(Path.Combine(TestPaths.Data, "buildings", "buildings.json")));
        JsonElement[] items = doc.RootElement.GetProperty("items").EnumerateArray().ToArray();

        Assert.Equal(items.Select(i => i.GetProperty("id").GetString()).Order(StringComparer.Ordinal), BuildingArt.All.Select(b => b.Id).Order(StringComparer.Ordinal));
        foreach (JsonElement item in items)
        {
            string id = item.GetProperty("id").GetString()!;
            BuildingSpec spec = BuildingArt.All.Single(b => b.Id == id);
            JsonElement footprint = item.GetProperty("footprint");
            Assert.Equal((footprint.GetProperty("width").GetInt32(), footprint.GetProperty("height").GetInt32()), (spec.Width, spec.Height));
            Assert.Equal(item.GetProperty("levels").GetArrayLength(), spec.Levels);
        }
    }

    [Fact]
    public void EveryBuildingLevelAndStageHasAFrameOfTheRightSize()
    {
        ArtOutput art = ArtGenerator.Generate();
        Dictionary<string, AtlasCell> byId = art.Cells.ToDictionary(c => c.Id, StringComparer.Ordinal);
        int expected = 0;
        foreach (BuildingSpec b in BuildingArt.All)
        {
            for (int level = 1; level <= b.Levels; level++)
            {
                for (int stage = 0; stage < 4; stage++)
                {
                    expected++;
                    string id = $"{b.Id}_l{level}_s{stage}";
                    Assert.True(byId.TryGetValue(id, out AtlasCell? cell), id + " is missing");
                    int sum = b.Width + b.Height;
                    Assert.Equal("buildings", cell.Atlas);
                    Assert.Equal("building", cell.Kind);
                    Assert.Equal(16 * sum, cell.W);
                    Assert.Equal((8 * sum) + b.Rise, cell.H);
                    Assert.Equal((cell.W / 2, cell.H - 1), (cell.OriginX, cell.OriginY));
                    Assert.Equal((0, stage), (cell.Height, cell.Variant));

                    // The origin (bottom corner of the footprint diamond) is painted and nothing is clipped at the frame's top row.
                    Assert.NotEqual(0, art.Buildings.Get(cell.X + cell.OriginX, cell.Y + cell.OriginY).A);
                    for (int x = 0; x < cell.W; x++)
                    {
                        Assert.Equal(0, art.Buildings.Get(cell.X + x, cell.Y).A);
                    }
                }
            }
        }

        Assert.Equal(expected, art.Cells.Count(c => c.Kind == "building"));
    }

    [Fact]
    public void BuildingStagesAndLevelsLookDifferent()
    {
        foreach (BuildingSpec b in BuildingArt.All)
        {
            for (int level = 1; level <= b.Levels; level++)
            {
                byte[][] stages = Enumerable.Range(0, 4).Select(s => BuildingArt.Draw(b, level, s).Pixels).ToArray();
                for (int i = 0; i < 4; i++)
                {
                    for (int j = i + 1; j < 4; j++)
                    {
                        Assert.False(stages[i].AsSpan().SequenceEqual(stages[j]), $"{b.Id} level {level}: stages {i} and {j} are identical");
                    }
                }
            }

            for (int level = 2; level <= b.Levels; level++)
            {
                Assert.False(BuildingArt.Draw(b, level - 1, 3).Pixels.AsSpan().SequenceEqual(BuildingArt.Draw(b, level, 3).Pixels), $"{b.Id} levels {level - 1} and {level} are identical");
            }
        }
    }

    [Fact]
    public void TableJsonMatchesTheCells()
    {
        ArtOutput art = ArtGenerator.Generate();
        using JsonDocument doc = JsonDocument.Parse(art.AtlasJson);
        JsonElement cells = doc.RootElement.GetProperty("cells");

        Assert.Equal(art.Cells.Count, cells.GetArrayLength());
        Assert.Equal((32, 16, 8), (TileArt.TileWidth, TileArt.TileHeight, TileArt.HeightStep));
        Assert.Equal(TileArt.TileWidth, doc.RootElement.GetProperty("tileWidth").GetInt32());
        Assert.Equal(TileArt.TileHeight, doc.RootElement.GetProperty("tileHeight").GetInt32());
        Assert.Equal(TileArt.HeightStep, doc.RootElement.GetProperty("heightStep").GetInt32());
        for (int i = 0; i < art.Cells.Count; i++)
        {
            Assert.Equal(art.Cells[i].Id, cells[i].GetProperty("id").GetString());
            Assert.Equal(art.Cells[i].Y, cells[i].GetProperty("y").GetInt32());
        }
    }

    [Theory]
    [InlineData("tiles")]
    [InlineData("objects")]
    [InlineData("buildings")]
    public void PngDecodesAndChunkCrcsAreValid(string atlas)
    {
        ArtOutput art = ArtGenerator.Generate();
        (byte[] png, Canvas canvas) = atlas switch
        {
            "tiles" => (art.TilesPng, art.Tiles),
            "objects" => (art.ObjectsPng, art.Objects),
            _ => (art.BuildingsPng, art.Buildings),
        };

        Assert.True(png.AsSpan(0, 8).SequenceEqual(new byte[] { 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A }));
        int pos = 8;
        string order = string.Empty;
        using MemoryStream idat = new();
        while (pos < png.Length)
        {
            int len = (int)BinaryPrimitives.ReadUInt32BigEndian(png.AsSpan(pos));
            string type = System.Text.Encoding.ASCII.GetString(png, pos + 4, 4);
            uint crc = BinaryPrimitives.ReadUInt32BigEndian(png.AsSpan(pos + 8 + len));
            Assert.Equal(crc, PngWriter.Crc32(png.AsSpan(pos + 4, 4 + len)));
            if (type == "IHDR")
            {
                Assert.Equal((uint)canvas.Width, BinaryPrimitives.ReadUInt32BigEndian(png.AsSpan(pos + 8)));
                Assert.Equal((uint)canvas.Height, BinaryPrimitives.ReadUInt32BigEndian(png.AsSpan(pos + 12)));
                Assert.Equal(8, png[pos + 16]);
                Assert.Equal(6, png[pos + 17]);
            }
            else if (type == "IDAT")
            {
                idat.Write(png, pos + 8, len);
            }

            order += type + ",";
            pos += 12 + len;
        }

        Assert.Equal("IHDR,IDAT,IEND,", order);

        // The standard library's inflater must read our zlib stream back to the exact pixels.
        idat.Position = 0;
        using ZLibStream z = new(idat, CompressionMode.Decompress);
        using MemoryStream raw = new();
        z.CopyTo(raw);
        byte[] bytes = raw.ToArray();
        int stride = (canvas.Width * 4) + 1;
        Assert.Equal(stride * canvas.Height, bytes.Length);
        for (int y = 0; y < canvas.Height; y++)
        {
            Assert.Equal(0, bytes[y * stride]);
            Assert.True(bytes.AsSpan((y * stride) + 1, stride - 1).SequenceEqual(canvas.Pixels.AsSpan(y * (stride - 1), stride - 1)));
        }
    }

    [Fact]
    public void CommittedArtEqualsRegeneratedArt()
    {
        ArtOutput art = ArtGenerator.Generate();
        AssertFile(ArtGenerator.TilesPath, art.TilesPng);
        AssertFile(ArtGenerator.ObjectsPath, art.ObjectsPng);
        AssertFile(ArtGenerator.BuildingsPath, art.BuildingsPng);
        AssertFile(ArtGenerator.TablePath, new System.Text.UTF8Encoding(false).GetBytes(art.AtlasJson));
        AssertFile(ArtGenerator.SchemaPath, new System.Text.UTF8Encoding(false).GetBytes(art.SchemaJson));
    }

    [Fact]
    public void AtlasTableValidatesAgainstItsSchema()
    {
        JsonSchema schema = JsonSchema.Build(JsonDocument.Parse(File.ReadAllText(Path.Combine(TestPaths.Data, "art", "atlas.schema.json"))).RootElement);
        using JsonDocument good = JsonDocument.Parse(File.ReadAllText(Path.Combine(TestPaths.Data, ArtGenerator.TablePath["data/".Length..])));
        Assert.True(schema.Evaluate(good.RootElement, new EvaluationOptions { OutputFormat = OutputFormat.Flag }).IsValid);

        string bad = """{ "tileWidth": 32, "tileHeight": 16, "heightStep": 8, "atlases": [], "cells": [] }""";
        using JsonDocument badDoc = JsonDocument.Parse(bad);
        Assert.False(schema.Evaluate(badDoc.RootElement, new EvaluationOptions { OutputFormat = OutputFormat.Flag }).IsValid);
    }

    private static void AssertFile(string relative, byte[] expected)
    {
        string path = Path.Combine(TestPaths.Root, relative);
        Assert.True(File.Exists(path), relative + " is missing; run tools/artgen.sh");
        Assert.True(File.ReadAllBytes(path).AsSpan().SequenceEqual(expected), relative + " is stale; run tools/artgen.sh");
    }
}
